"""`helpers/cfg.ts`: which django-cfg generated this client and the oldest one that serves the same contract."""

from __future__ import annotations

from django_cfg.core.contract import CFG_VERSION, CONTRACT_SINCE


def render_cfg_ts() -> str:
    return (
        "// AUTO-GENERATED by django_generator. DO NOT EDIT — re-run `make gen`.\n"
        "// `version`: the django-cfg that generated this client. `contract`: the oldest django-cfg that serves the same contract.\n"
        f"export const CFG = {{ version: '{CFG_VERSION}', contract: '{CONTRACT_SINCE}' }} as const;\n"
    )
